          let gameCR={
            exit:false
          };

          let pointHasShapes = true // master toggle
          let pointerData = {}
          let swipeThreshold = 20
          function pointerEventData(pData) {
            let nowTimeMs = new Date().getTime()
            switch (pData.event) {
              case 'pointerdown':
                // console.log('pointerdown:', pData)
                pointerData[pData.pointerID] = {
                  lastAngle: 0,
                  cumulativeAngle: 0,
                  startTime: nowTimeMs,
                  circleCount: 0,
                  triangleCorners: 0,
                  triangleCount: 0,
                  quadCorners: 0,
                  quadCount: 0,
                  //swipe
                  startX: pData.x,
                  startY: pData.y,
                  // have to reset before new shape
                  // sharpDistance: 0,
                  isShapeSizeOK: 0,
                  // shapeStartTime: scene.time.now,
                  path: [{ x: pData.x, y: pData.y }],
                }
                return {
                  pointerID: pData.pointerID,
                  event: 'pointerdown',
                  x: pData.x,
                  y: pData.y,
                  cx: pData.csX + pData.x,
                  cy: pData.csY - pData.y,
                  // dx: sDX | 0,
                  // dy: sDY | 0,
                  // speed: null,
                  // angle: angle,
                  // direction: this.getDirection(angle),
                  // swipe: swipe,
                  // shape: shape,
                }
                break
              case 'pointermove':
                {
                  const data = pointerData[pData.pointerID]
                  if (!data) return

                  // const now = this.time.now

                  let sDX = pData.x - data.startX //swipeDistanceX
                  let sDY = pData.y - data.startY //swipeDistanceY
                  // const dt = (now - data.startTime) / 1000 // seconds
                  // const speed = Math.sqrt(sDX * sDX + sDY * sDY) / dt // pixels/sec

                  let angle = ((Math.atan2(sDY, sDX) * 180) / Math.PI) | 0 // degrees
                  // let angle = Phaser.Math.RadToDeg(Math.atan2(sDY, sDX)) // Convert radian to degrees
                  angle = angle + 90
                  if (angle > 180) {
                    angle = angle - 360
                  }

                  let swipe = 'Tap'
                  let absX = Math.abs(sDX)
                  let absY = Math.abs(sDY)
                  // Detect swipe
                  if (absX > absY && absX > swipeThreshold) {
                    // Horizontal swipe
                    if (sDX > 0) {
                      swipe = 'Right'
                    } else {
                      swipe = 'Left'
                    }
                    // isSwipeDetected = true;
                  } else if (absY > absX && absY > swipeThreshold) {
                    // Vertical swipe
                    if (sDY > 0) {
                      swipe = 'Down'
                    } else {
                      swipe = 'Up'
                    }
                    // isSwipeDetected = true;
                  }
                  // end swipe

                  data.path.push({ x: pData.x, y: pData.y })
                  let shape = 'null'
                  if (pointHasShapes) {
                    // --- Circle detection ---
                    const sum = data.path.reduce((acc, p) => ({ x: acc.x + p.x, y: acc.y + p.y }), {
                      x: 0,
                      y: 0,
                    })
                    const center = { x: sum.x / data.path.length, y: sum.y / data.path.length }

                    if (data.isShapeSizeOK < 2) {
                      let distance = Phaser.Math.Distance.Between(
                        data.path[0].x,
                        data.path[0].y,
                        pData.x,
                        pData.y,
                      )
                      if (data.isShapeSizeOK == 0 && distance > 50) {
                        data.isShapeSizeOK = 1
                      } else if (data.isShapeSizeOK == 1 && distance < 30) {
                        // Back to nearly original point
                        data.isShapeSizeOK = 2
                      }
                    }
                    if (data.isShapeSizeOK > 0) {
                      // --- Triangle and Quadrilateral detection ---
                      if (data.path.length >= 3) {
                        const path = data.path
                        const a = path[path.length - 3]
                        const b = path[path.length - 2]
                        const c = path[path.length - 1]
                        const angle1 = Math.atan2(b.y - a.y, b.x - a.x)
                        const angle2 = Math.atan2(c.y - b.y, c.x - b.x)
                        let diff = Math.abs(angle2 - angle1)
                        if (diff > Math.PI) diff = 2 * Math.PI - diff

                        if (diff > Math.PI / 3) {
                          // >60° sharp corner
                          // Triangle
                          data.triangleCorners++
                          if (data.isShapeSizeOK > 1 && data.triangleCorners >= 3) {
                            data.triangleCount++
                            data.triangleCorners = 0
                            //reset
                            shape = 'triangle'
                            data.isShapeSizeOK = 0
                            // data.shapeStartTime = this.time.now
                            data.path = [{ x: pData.x, y: pData.y }] //clear
                          }

                          // // Quadrilateral (square or rectangle)
                          // data.quadCorners++
                          // if (data.isShapeSizeOK > 1 && data.quadCorners >= 4) {
                          //   data.quadCount++
                          //   data.quadCorners = 0
                          //   //reset
                          // shape="quadrilateral"
                          //   data.isShapeSizeOK = 0
                          //   // data.shapeStartTime = this.time.now
                          //   data.path = [{ x: pData.x, y: pData.y }] //clear
                          // }
                        }
                      }
                    }
                    if (data.isShapeSizeOK > 1) {
                      const dxC = pData.x - center.x
                      const dyC = pData.y - center.y
                      const ang = Math.atan2(dyC, dxC)
                      let delta = ang - data.lastAngle
                      if (delta > Math.PI) delta -= 2 * Math.PI
                      if (delta < -Math.PI) delta += 2 * Math.PI
                      data.cumulativeAngle += delta
                      data.lastAngle = ang

                      while (data.cumulativeAngle >= 2 * Math.PI) {
                        data.circleCount++
                        data.cumulativeAngle -= 2 * Math.PI
                        //reset
                        shape = 'circle'
                        data.isShapeSizeOK = 0
                        // data.shapeStartTime = this.time.now
                        data.path = [{ x: pData.x, y: pData.y }] //clear
                      }
                      while (data.cumulativeAngle <= -2 * Math.PI) {
                        data.circleCount++
                        data.cumulativeAngle += 2 * Math.PI
                        //reset
                        shape = 'circle'
                        data.isShapeSizeOK = 0
                        // data.shapeStartTime = this.time.now
                        data.path = [{ x: pData.x, y: pData.y }] //clear
                      }
                    }
                  }
                  if (data.path.length > 255) {
                    //reset
                    data.isShapeSizeOK = 0
                    // data.shapeStartTime = this.time.now
                    data.path = [{ x: pData.x, y: pData.y }] //clear
                  }
                  return {
                    pointerID: pData.pointerID,
                    event: 'pointermove',
                    x: data.startX,
                    y: data.startY,
                    cx: pData.csX + pData.x,
                    cy: pData.csY - pData.y,
                    dx: sDX | 0,
                    dy: sDY | 0,
                    // speed: null,
                    angle: angle,
                    // direction: this.getDirection(angle),
                    swipe: swipe,
                    shape: shape,
                  }
                }
                break
              default: //pointerup
                const data = pointerData[pData.pointerID]
                if (!data) return
                // angle for point up
                // //start swipt left right
                let sDX = pData.x - data.startX //swipeDistanceX
                let sDY = pData.y - data.startY //swipeDistanceY
                const dt = (nowTimeMs - data.startTime) / 1000 // seconds
                const speed = Math.sqrt(sDX * sDX + sDY * sDY) / dt // pixels/sec

                let angle = ((Math.atan2(sDY, sDX) * 180) / Math.PI) | 0 // degrees
                // let angle = Phaser.Math.RadToDeg(Math.atan2(sDY, sDX)) // Convert radian to degrees
                angle = angle + 90
                if (angle > 180) {
                  angle = angle - 360
                }

                let swipe = 'Tap'
                let absX = Math.abs(sDX)
                let absY = Math.abs(sDY)
                // Detect swipe
                if (absX > absY && absX > swipeThreshold) {
                  // Horizontal swipe
                  if (sDX > 0) {
                    swipe = 'Right'
                  } else {
                    swipe = 'Left'
                  }
                } else if (absY > absX && absY > swipeThreshold) {
                  // Vertical swipe
                  if (sDY > 0) {
                    swipe = 'Down'
                  } else {
                    swipe = 'Up'
                  }
                }
                // delete pointerData[pointer.id] reset while down
                return {
                  pointerID: pData.pointerID,
                  event: 'pointerup',
                  x: pData.x,
                  y: pData.y,
                  cx: pData.csX + pData.x,
                  cy: pData.csY - pData.y,

                  dx: sDX,
                  dy: sDY,
                  speed: speed | 0,
                  angle: angle,
                  swipe: swipe,
                }
            }
          }

